/* Reconstructed from compiled CSS — original SCSS structure (mixins, nesting, $vars, @imports) is lost.
   Class names are recovered; rules are flat CSS that compiles as SCSS. */

:export {
  viewport_rf_width: 2800;
  viewport_rf_height: 1600;
  viewport_flex_height: min(57vw, 100vh);
  safeArea_paddingLeft: var(--safeArea_paddingLeft);
  safeArea_paddingRight: var(--safeArea_paddingRight);
  safeArea_paddingBottom: var(--safeArea_paddingBottom);
}

.rootContainer {
  width: 100%;
  height: 100%;
  position: relative;
  background-size: cover;
  background-position: center;
  overflow: hidden;
  text-align: center;
}

.mainBox {
  display: flex;
  flex-direction: column;
  position: relative;
  width: 100%;
  height: 100%;
  background-size: cover;
  background-position: center;
  padding-bottom: calc(min(57vw, 100vh) * 0.0875);
}

.contentBox {
  display: flex;
  flex: 1 1;
}

.leftBox {
  position: relative;
  width: 40%;
}

.rightBox {
  position: relative;
  flex: 1 1;
}

.rightBoxCont {
  position: absolute;
  left: 50%;
  top: 60%;
  -webkit-transform: translate(-50%, -50%);
  transform: translate(-50%, -50%);
  width: 70%;
  display: flex;
  flex-direction: column;
}

.selectedItemBox {
  position: absolute;
  left: 0;
  top: 0;
  width: 113%;
}

.bgSelectedItem {
  width: 100%;
}

.selectedItemImg {
  position: absolute;
  left: 50%;
  top: 50%;
  height: 60%;
  -webkit-transform: translate(-60%, -60%);
  transform: translate(-60%, -60%);
}

.itemNameBox {
  font-size: calc(min(57vw, 100vh) * 0.0625);
  font-weight: 700;
  font-family: 'Noto Serif TC';
  font-family: var(--font_noto_serif);
  color: #5b5b5b;
}

.panelBox {
  display: flex;
  width: 100%;
  align-items: center;
}

.panelCenter {
  width: 45%;
  font-size: calc(min(57vw, 100vh) * 0.0475);
  font-weight: 700;
  font-family: 'Gelasio';
  font-family: var(--font_text_figures);
  color: #5b5b5b;
}

.panelLeft {
  display: flex;
  flex: 1 1;
  justify-content: right;
}

.panelRight {
  display: flex;
  flex: 1 1;
  justify-content: left;
}

.quantityBtn {
  height: calc(min(57vw, 100vh) * 0.035);
  margin: 10px;
}

.footer {
  display: flex;
  justify-content: center;
  align-items: center;
  position: relative;
  height: 25%;
}

.sliderBox {
  width: 100%;
  height: calc(min(57vw, 100vh) * 0.1375);
  display: flex;
  align-items: center;
  justify-content: center;
}

.vertical_slider {
  height: calc(min(57vw, 100vh) * 0.025);
  background-color: #fff;
  box-shadow: 0px 0px 20px 10px rgba(125, 125, 125, 0.5);
}

.vertical_slider .range-slider__range {
  background: unset;
}

.vertical_slider .range-slider__thumb {
  position: absolute;
  z-index: 3;
  top: 50%;
  width: calc(min(57vw, 100vh) * 0.0625);
  height: calc(min(57vw, 100vh) * 0.0625);
  -webkit-transform: translate(-50%, -50%);
  transform: translate(-50%, -50%);
  border-radius: 50%;
  background: #787878;
}

.vertical_slider .range-slider__thumb[data-lower] {
  width: 0;
}
