/* Reconstructed from compiled CSS — original SCSS structure (mixins, nesting, $vars, @imports) is lost.
   Class names are recovered; rules are flat CSS that compiles as SCSS. */

:export {
  viewport_rf_width: 2800;
  viewport_rf_height: 1600;
  viewport_flex_height: min(57vw, 100vh);
  safeArea_paddingLeft: var(--safeArea_paddingLeft);
  safeArea_paddingRight: var(--safeArea_paddingRight);
  safeArea_paddingBottom: var(--safeArea_paddingBottom);
}

.rootContainer {
  width: 100%;
  height: 100%;
  position: relative;
  background-size: cover;
  background-position: center;
  overflow: hidden;
  text-align: center;
}

.mainBox {
  display: inline-block;
  position: relative;
  width: 100%;
  height: 100%;
  background-size: cover;
  background-position: center;
  color: #fff;
}

.bgBox {
  position: absolute;
  left: 0;
  top: 0;
  height: 100%;
}

.bgImg {
  position: absolute;
  left: 0;
  top: 0;
  height: 130%;
  -webkit-transform: translate(-12%, -13%);
  transform: translate(-12%, -13%);
}

.bgImg_chain {
  position: absolute;
  left: 0;
  top: 0;
  height: 130%;
  -webkit-transform: translate(-10%, -13%);
  transform: translate(-10%, -13%);
}

.leftBox {
  position: absolute;
  top: 0;
  left: 0;
  display: inline-block;
  width: 48%;
  height: 100%;
}

.foundsBox {
  position: absolute;
  left: 3vw;
  top: calc(min(57vw, 100vh) * 0.02875);
  height: calc(min(57vw, 100vh) * 0.071875);
  font-size: calc(min(57vw, 100vh) * 0.025);
}

.foundsBox .itemIcon {
  height: 100%;
  display: inline-block;
}

.foundsBox .itemText {
  display: inline-block;
  font-family: 'Gelasio';
  font-family: var(--font_text_figures);
  font-weight: bold;
}

.statusText {
  position: absolute;
  left: 3vw;
  top: calc(min(57vw, 100vh) * 0.114375);
  font-size: calc(min(57vw, 100vh) * 0.06625);
  font-family: 'Noto Sans TC';
  font-family: var(--font_noto_sans);
  font-weight: bold;
}

.missionDescription {
  position: absolute;
  left: calc(min(57vw, 100vh) * 0.19375);
  top: calc(min(57vw, 100vh) * 0.224375);
  font-size: calc(min(57vw, 100vh) * 0.035);
  text-align: left;
  font-family: 'Noto Sans TC';
  font-family: var(--font_noto_sans);
  font-weight: bold;
}

.winCondition {
  position: absolute;
  left: 3vw;
  top: calc(min(57vw, 100vh) * 0.74625);
  font-size: calc(min(57vw, 100vh) * 0.035);
  text-align: left;
  font-family: 'Noto Sans TC';
  font-family: var(--font_noto_sans);
}

.rightBox {
  position: absolute;
  top: 0;
  right: 0;
  display: inline-block;
  width: 50%;
  height: 100%;
  background-position: center;
  background-size: cover;
  color: #fff;
  padding: 1% 1%;
}

.cityName {
  width: 100%;
  height: calc(min(57vw, 100vh) * 0.1075);
  font-size: calc(min(57vw, 100vh) * 0.0625);
  font-weight: 900;
  padding-top: 2%;
  font-family: 'Noto Serif TC';
  font-family: var(--font_noto_serif);
}

.city_point_description {
  height: calc(min(57vw, 100vh) * 0.03125);
  font-size: calc(min(57vw, 100vh) * 0.03125);
  font-weight: bold;
  margin-top: calc(min(57vw, 100vh) * 0.00625);
  margin-bottom: calc(min(57vw, 100vh) * 0.0125);
  line-height: 1;
}

.cityImg {
  height: calc(min(57vw, 100vh) * 0.240625);
}

.missionNameBox {
  position: absolute;
  left: 0;
  top: calc(min(57vw, 100vh) * 0.801875);
  width: calc(min(57vw, 100vh) * 0.5125);
  height: calc(min(57vw, 100vh) * 0.075625);
  font-size: calc(min(57vw, 100vh) * 0.03375);
  text-align: center;
  display: inline-block;
}

.missionNameBox img {
  height: 100%;
  width: 100%;
}

.missionName {
  position: absolute;
  left: 50%;
  top: 50%;
  -webkit-transform: translate(-50%, -50%);
  transform: translate(-50%, -50%);
  font-family: 'Noto Serif TC';
  font-family: var(--font_noto_serif);
  font-weight: 900;
}

.missionNoL {
  position: absolute;
  left: 0;
  top: 0;
  color: #000;
  font-size: calc(min(57vw, 100vh) * 0.02875);
  font-family: 'Gelasio';
  font-family: var(--font_text_figures);
  font-weight: bold;
}

.missionNoR {
  position: absolute;
  right: 0;
  bottom: 0;
  color: #000;
  font-size: calc(min(57vw, 100vh) * 0.0375);
  font-family: 'Gelasio';
  font-family: var(--font_text_figures);
  font-weight: bold;
}

.chapterNameBox {
  position: absolute;
  left: 0;
  top: calc(min(57vw, 100vh) * 0.900625);
  width: calc(min(57vw, 100vh) * 0.5125);
  height: calc(min(57vw, 100vh) * 0.0575);
  font-size: calc(min(57vw, 100vh) * 0.03375);
  text-align: center;
  display: inline-block;
}

.chapterNameBox img {
  height: 100%;
  width: 100%;
}

.chapterName {
  position: absolute;
  left: 50%;
  top: 50%;
  -webkit-transform: translate(-50%, -50%);
  transform: translate(-50%, -50%);
  font-family: 'Noto Sans TC';
  font-family: var(--font_noto_sans);
}

.btnCircleBox {
  position: absolute;
  right: 0;
  bottom: 0;
  width: calc(min(57vw, 100vh) * 0.3625);
  height: calc(min(57vw, 100vh) * 0.2625);
  overflow: hidden;
}

.btnCircleWrap {
  display: inline-block;
  position: relative;
}

.btnCircleGold {
  width: calc(min(57vw, 100vh) * 0.425);
}

.btnCircleBox2 {
  position: absolute;
  right: calc(min(57vw, 100vh) * 0.37813);
  bottom: 0;
  width: calc(min(57vw, 100vh) * 0.3625);
  height: calc(min(57vw, 100vh) * 0.2625);
  overflow: visible;
}

.btnCircleText {
  position: absolute;
  left: 50%;
  top: 40%;
  font-size: calc(min(57vw, 100vh) * 0.05375);
  -webkit-transform: translate(-50%, -50%);
  transform: translate(-50%, -50%);
}

.winPrizesBar {
  position: absolute;
  width: 100%;
  height: calc(min(57vw, 100vh) * 0.284375);
  top: calc(min(57vw, 100vh) * 0.4375);
  background-size: 100% 100%;
  background-position: center;
  display: flex;
  justify-content: center;
  align-items: center;
}

.prizeItem {
  height: calc(min(57vw, 100vh) * 0.34625);
  display: inline-block;
  position: relative;
  margin: 0 -2% 0 -2%;
}

.bgPrizeItem {
  height: 100%;
  display: inline-block;
  opacity: 0.7;
}

.prizeImg {
  position: absolute;
  left: 50%;
  top: 50%;
  -webkit-transform: translate(-50%, -50%);
  transform: translate(-50%, -50%);
  height: 50%;
  display: inline-block;
}

.icon_seal_achieved {
  position: absolute;
  left: 50%;
  bottom: 21%;
  -webkit-transform: translate(-50%, 0);
  transform: translate(-50%, 0);
  height: 24%;
  display: inline-block;
  pointer-events: none;
}

.prizeQuantity {
  font-size: calc(min(57vw, 100vh) * 0.025);
  position: absolute;
  left: 70%;
  bottom: 18%;
  font-weight: bolder;
  font-family: 'Gelasio';
  font-family: var(--font_text_figures);
}

.firstTimeText {
  font-size: calc(min(57vw, 100vh) * 0.025);
  position: absolute;
  right: 70%;
  top: 18%;
  font-weight: bolder;
  font-family: 'Noto Sans TC';
  font-family: var(--font_noto_sans);
}
