/* Reconstructed from compiled CSS — original SCSS structure (mixins, nesting, $vars, @imports) is lost.
   Class names are recovered; rules are flat CSS that compiles as SCSS. */

:export {
  viewport_rf_width: 2800;
  viewport_rf_height: 1600;
  viewport_flex_height: min(57vw, 100vh);
  safeArea_paddingLeft: var(--safeArea_paddingLeft);
  safeArea_paddingRight: var(--safeArea_paddingRight);
  safeArea_paddingBottom: var(--safeArea_paddingBottom);
}

.rootContainer {
  width: 100%;
  height: 100%;
  position: relative;
  background-size: cover;
  background-position: center;
  overflow: hidden;
  text-align: center;
}

.mainBox {
  display: inline-block;
  position: relative;
  width: 100%;
  height: 100%;
  color: #fff;
}

.leftBox {
  position: absolute;
  top: 0;
  left: 0;
  display: inline-block;
  width: 49%;
  height: 100%;
  background-color: #000;
}

.rightBox {
  position: absolute;
  top: 0;
  right: 0;
  display: inline-block;
  width: 50%;
  height: 100%;
  background-color: #000;
  background-position: center;
  background-size: cover;
  color: #fff;
  padding: 1% 1%;
}

.cityTitle {
  position: relative;
  height: calc(min(57vw, 100vh) * 0.07);
  margin-top: 2%;
}

.cityName {
  position: absolute;
  font-size: calc(min(57vw, 100vh) * 0.0625);
  font-weight: 900;
  display: inline-block;
  left: 50%;
  top: 50%;
  -webkit-transform: translate(-50%, -50%);
  transform: translate(-50%, -50%);
  line-height: 1;
  font-family: 'Noto Serif TC';
  font-family: var(--font_noto_serif);
}

.city_point_description {
  height: calc(min(57vw, 100vh) * 0.03125);
  font-size: calc(min(57vw, 100vh) * 0.03125);
  font-weight: bold;
  margin-top: calc(min(57vw, 100vh) * 0.00625);
  margin-bottom: calc(min(57vw, 100vh) * 0.0125);
  line-height: 1;
}

.nameArrowL {
  display: inline-block;
  position: absolute;
  left: 15%;
  top: 50%;
  -webkit-transform: translateY(-50%);
  transform: translateY(-50%);
}

.nameArrowR {
  display: inline-block;
  position: absolute;
  right: 15%;
  top: 50%;
  -webkit-transform: translateY(-50%);
  transform: translateY(-50%);
}

.arrowImg {
  height: calc(min(57vw, 100vh) * 86 / 1600);
}

.cityImg {
  height: calc(min(57vw, 100vh) * 0.240625);
}

.cityDataBox {
  height: calc(min(57vw, 100vh) * 0.381875);
  position: relative;
}

.dataRowHead {
  height: calc(min(57vw, 100vh) * 0.070625);
  font-size: calc(min(57vw, 100vh) * 0.03375);
  font-family: 'Noto Serif TC';
  font-family: var(--font_noto_serif);
  font-weight: bold;
}

.dataRowHead::before {
  content: '';
  display: inline-block;
  height: 100%;
  width: 0;
  vertical-align: bottom;
}

.dataRow {
  height: calc(min(57vw, 100vh) * 0.05375);
  font-size: calc(min(57vw, 100vh) * 0.03375);
  margin: 1.5% 0 0 0;
  font-family: 'Noto Sans TC';
  font-family: var(--font_noto_sans);
  font-weight: bold;
}

.dataRow::before {
  content: '';
  display: inline-block;
  height: 100%;
  width: 0;
  vertical-align: middle;
}

.dataRowBg {
  background-size: 100% 100%;
}

.flag {
  height: calc(min(57vw, 100vh) * 0.400625);
}

.flagLeft {
  position: absolute;
  left: 0;
  top: 0;
}

.flagRight {
  position: absolute;
  right: 0;
  top: 0;
}

.nation_battle_nation_icon {
  width: calc(min(57vw, 100vh) * 0.04375);
  position: absolute;
  left: 50%;
  top: 45%;
  -webkit-transform: translate(-50%, -50%);
  transform: translate(-50%, -50%);
  -webkit-filter: drop-shadow(0 0 0.5rem rgba(0, 0, 0, 0.7));
  filter: drop-shadow(0 0 0.5rem rgba(0, 0, 0, 0.7));
}

.nation_battle_close_roll_call_at {
  position: absolute;
  left: 50%;
  top: 70%;
  -webkit-transform: translate(-50%, -50%);
  transform: translate(-50%, -50%);
  font-size: calc(min(57vw, 100vh) * 0.02375);
  font-family: 'Gelasio';
  font-family: var(--font_text_figures);
  font-weight: bold;
}

.icon_2knifes {
  width: calc(min(57vw, 100vh) * 0.196875);
  position: absolute;
  left: 50%;
  top: 50%;
  -webkit-transform: translate(-50%, -50%);
  transform: translate(-50%, -50%);
}

.missionNameBox {
  position: absolute;
  left: 0;
  top: calc(min(57vw, 100vh) * 0.801875);
  width: calc(min(57vw, 100vh) * 0.5125);
  height: calc(min(57vw, 100vh) * 0.075625);
  font-size: calc(min(57vw, 100vh) * 0.03375);
  text-align: center;
  display: inline-block;
}

.missionNameBox img {
  height: 100%;
  width: 100%;
}

.missionName {
  position: absolute;
  left: 50%;
  top: 50%;
  -webkit-transform: translate(-50%, -50%);
  transform: translate(-50%, -50%);
  font-family: 'Noto Serif TC';
  font-family: var(--font_noto_serif);
  font-weight: 900;
}

.missionNoL {
  position: absolute;
  left: 0;
  top: 0;
  color: #000;
  font-size: calc(min(57vw, 100vh) * 0.02875);
  font-family: 'Gelasio';
  font-family: var(--font_text_figures);
  font-weight: bold;
}

.missionNoR {
  position: absolute;
  right: 0;
  bottom: 0;
  color: #000;
  font-size: calc(min(57vw, 100vh) * 0.0375);
  font-family: 'Gelasio';
  font-family: var(--font_text_figures);
  font-weight: bold;
}

.chapterNameBox {
  position: absolute;
  left: 0;
  top: calc(min(57vw, 100vh) * 0.900625);
  width: calc(min(57vw, 100vh) * 0.5125);
  height: calc(min(57vw, 100vh) * 0.0575);
  font-size: calc(min(57vw, 100vh) * 0.03375);
  text-align: center;
  display: inline-block;
}

.chapterNameBox img {
  height: 100%;
  width: 100%;
}

.chapterName {
  position: absolute;
  left: 50%;
  top: 50%;
  width: 100%;
  -webkit-transform: translate(-50%, -50%);
  transform: translate(-50%, -50%);
  font-family: 'Noto Sans TC';
  font-family: var(--font_noto_sans);
  font-weight: bold;
}

.btnCircleBox {
  position: absolute;
  right: 0;
  bottom: 0;
  width: calc(min(57vw, 100vh) * 0.3625);
  height: calc(min(57vw, 100vh) * 0.2625);
  overflow: hidden;
}

.btnCircleWrap {
  display: inline-block;
  position: relative;
  width: calc(min(57vw, 100vh) * 0.425);
  height: calc(min(57vw, 100vh) * 0.425);
}

.btnCircleGold {
  width: 100%;
  height: 100%;
  left: 0;
  top: 0;
  position: absolute;
}

.btnCircleText {
  position: absolute;
  left: 50%;
  top: 40%;
  font-size: calc(min(57vw, 100vh) * 0.05375);
  -webkit-transform: translate(-50%, -50%);
  transform: translate(-50%, -50%);
}

.markerCityBox {
  position: relative;
  width: calc(min(57vw, 100vh) * 0.125);
  height: calc(min(57vw, 100vh) * 0.125);
  -webkit-transform: translate(-50%, -50%);
  transform: translate(-50%, -50%);
}

.markerCityBox_inline {
  position: absolute;
  left: 50%;
  top: 50%;
  width: calc(min(57vw, 100vh) * 0.125 * 2);
  height: calc(min(57vw, 100vh) * 0.125 * 2);
  -webkit-transform: translate(-50%, -50%);
  transform: translate(-50%, -50%);
  pointer-events: none;
}

.animatedRing {
  position: absolute;
  left: 50%;
  top: 50%;
  height: calc(min(57vw, 100vh) * 0.34375);
  -webkit-transform: translate(-50%, -50%);
  transform: translate(-50%, -50%);
  pointer-events: none;
}

.animatedRing img {
  height: 100%;
}

.markerCityIcon {
  width: 100%;
  height: 100%;
}

.markerClickSensor {
  position: absolute;
  left: 0;
  top: 0;
  width: 100%;
  height: 100%;
}

.markerBuildingIcon {
  position: absolute;
  left: 0;
  top: 0;
  height: 100%;
}

.markerCityName {
  position: absolute;
  left: 50%;
  bottom: 0;
  -webkit-transform: translate(-50%, 0);
  transform: translate(-50%, 0);
  font-size: calc(min(57vw, 100vh) * 0.04375);
  font-weight: bold;
  text-shadow: #000 0.1em 0.1em 0.2em;
  white-space: nowrap;
}

.marker2swords {
  height: calc(min(57vw, 100vh) * 0.0625);
  -webkit-transform: translateY(-50%);
  transform: translateY(-50%);
}

.mapPanelLB {
  position: absolute;
  left: calc(min(57vw, 100vh) * 0.01375);
  bottom: calc(min(57vw, 100vh) * 0.01375);
  z-index: 500;
  display: flex;
}

.icon_unionFlag {
  width: calc(min(57vw, 100vh) * 0.1);
}

.mapPanelLB_text {
  font-size: calc(min(57vw, 100vh) * 0.02625);
  font-weight: bold;
  display: flex;
  align-items: end;
}

.hqBox {
  position: absolute;
  left: 50%;
  top: 50%;
  -webkit-transform: translate(-50%, -50%);
  transform: translate(-50%, -50%);
}

.hqBox img {
  height: calc(min(57vw, 100vh) * 0.089375);
}

.hqWord {
  font-size: calc(min(57vw, 100vh) * 0.029375);
  font-weight: bold;
  font-family: 'Noto Sans TC';
  font-family: var(--font_noto_sans);
  white-space: nowrap;
}

.cityBox {
  position: relative;
}
