/* Reconstructed from compiled CSS — original SCSS structure (mixins, nesting, $vars, @imports) is lost.
   Class names are recovered; rules are flat CSS that compiles as SCSS. */

:export {
  viewport_rf_width: 2800;
  viewport_rf_height: 1600;
  viewport_flex_height: min(57vw, 100vh);
  safeArea_paddingLeft: var(--safeArea_paddingLeft);
  safeArea_paddingRight: var(--safeArea_paddingRight);
  safeArea_paddingBottom: var(--safeArea_paddingBottom);
  lineWidth: 1px;
}

.rootContainer {
  width: 100%;
  height: 100%;
  position: relative;
  background-size: cover;
  background-position: center;
  overflow: hidden;
  text-align: center;
}

.mainBox {
  display: inline-block;
  position: relative;
  width: 100%;
  height: 100%;
  background-size: cover;
  background-position: center;
  color: #fff;
}

.leftBox {
  position: absolute;
  left: 0;
  width: 19.2857142857%;
  top: 0;
  height: 100%;
  padding-top: 1rem;
}

.rightBox {
  position: absolute;
  right: 4rem;
  left: 19.2857142857%;
  top: 0;
  height: 100%;
  padding-top: calc(min(57vw, 100vh) * 40 / 1600);
  display: flex;
  justify-content: center;
}

.bgGunsL {
  height: calc(min(57vw, 100vh) * 1350 / 1600);
  position: absolute;
  left: 0;
  bottom: 0;
  -webkit-transform: translate(-29%, 20%);
  transform: translate(-29%, 20%);
  opacity: 0.1;
}

.bgStrategyTape {
  width: calc(min(57vw, 100vh) * 2000 / 1600);
  height: calc(min(57vw, 100vh) * 400 / 1600);
  position: absolute;
  left: 0;
  bottom: 0;
  color: #000;
  font-size: calc(min(57vw, 100vh) * 85 / 1600);
  font-weight: bold;
  background-size: cover;
  background-position: center;
  display: flex;
  align-items: center;
  justify-content: center;
  -webkit-transform: rotate(43deg) translate(-28%, 95%) scale(1.1);
  transform: rotate(43deg) translate(-28%, 95%) scale(1.1);
}

.strategyTapeText {
  display: flex;
  justify-content: center;
  align-items: center;
  width: 36%;
  height: 30%;
}

.catItemBox {
  width: 100%;
  height: calc(min(57vw, 100vh) * 310 / 1600);
  display: flex;
  align-items: center;
  justify-content: center;
}

.itemIconBox {
  position: relative;
  width: 100%;
  height: calc(min(57vw, 100vh) * 185 / 1600);
  margin-top: calc(min(57vw, 100vh) * 20 / 1600);
}

.itemBgBox {
  position: absolute;
  left: 50%;
  top: 50%;
  -webkit-transform: translate(-50%, -50%) scale(1.5);
  transform: translate(-50%, -50%) scale(1.5);
}

.itemBg {
  height: calc(min(57vw, 100vh) * 300 / 1600);
  -webkit-animation: Strategy_rotation__YNKjL 24s infinite linear;
  animation: Strategy_rotation__YNKjL 24s infinite linear;
}

.itemIcon {
  position: absolute;
  left: 50%;
  top: 50%;
  -webkit-transform: translate(-50%, -50%) scale(1.5);
  transform: translate(-50%, -50%) scale(1.5);
  height: calc(min(57vw, 100vh) * 300 / 1600);
}

.itemIcon_ds {
  position: absolute;
  left: 50%;
  top: 50%;
  -webkit-transform: translate(-50%, -50%) scale(1.2);
  transform: translate(-50%, -50%) scale(1.2);
  height: calc(min(57vw, 100vh) * 300 / 1600);
}

.itemText {
  position: relative;
  font-size: calc(min(57vw, 100vh) * 45 / 1600);
  line-height: calc(min(57vw, 100vh) * 50 / 1600);
  font-family: 'Noto Sans TC';
  font-family: var(--font_noto_sans);
  font-weight: bold;
}

.itemText_ds {
  position: relative;
  font-size: calc(min(57vw, 100vh) * 45 / 1600);
  line-height: calc(min(57vw, 100vh) * 50 / 1600);
  font-family: 'Noto Sans TC';
  font-family: var(--font_noto_sans);
  font-weight: bold;
  white-space: nowrap;
}

.itemsHead {
  display: flex;
  justify-content: center;
  position: relative;
}

.itemsBody {
  display: flex;
}

.itemBox {
  width: calc(min(57vw, 100vh) * 270 / 1600);
  height: calc(min(57vw, 100vh) * 320 / 1600);
  display: flex;
  justify-content: center;
  position: relative;
}

.lineV {
  position: absolute;
  width: 1px;
  height: 100%;
  bottom: 50%;
  background-color: #4a4a4a;
}

.lineV.top50 {
  height: 50%;
  bottom: 50%;
}

.lineV.bottom50 {
  height: 50%;
  top: 50%;
}

.lineV.none {
  display: none;
}

.lineH {
  position: absolute;
  height: 1px;
  bottom: 0;
  left: 0;
  right: 0;
}

.lineH.bg {
  background-color: #4a4a4a;
  left: 50%;
  -webkit-transform: translateX(-50%);
  transform: translateX(-50%);
}

.itemInfoBox {
  position: absolute;
  right: calc(min(57vw, 100vh) * 620 / 1600);
  bottom: calc(min(57vw, 100vh) * 50 / 1600);
  color: #fff;
  display: flex;
  flex-direction: column;
  justify-content: right;
  align-items: end;
  font-family: 'Noto Sans TC';
  font-family: var(--font_noto_sans);
}

.itemName {
  font-size: calc(min(57vw, 100vh) * 66 / 1600);
  font-weight: 900;
}

.itemDescription {
  font-size: calc(min(57vw, 100vh) * 52 / 1600);
  line-height: calc(min(57vw, 100vh) * 62 / 1600);
  font-weight: 900;
  text-align: right;
}

.itemDescription.twolines {
  height: calc(min(57vw, 100vh) * 62 / 1600 * 2);
}

.arrowL {
  position: absolute;
  right: 3vw;
  top: calc(min(57vw, 100vh) * 530 / 1600);
  -webkit-transform: translate(-35%, 0%);
  transform: translate(-35%, 0%);
}

.arrowR {
  position: absolute;
  right: 3vw;
  top: calc(min(57vw, 100vh) * 840 / 1600);
  -webkit-transform: translate(-35%, 0%);
  transform: translate(-35%, 0%);
}
