/* Reconstructed from compiled CSS — original SCSS structure (mixins, nesting, $vars, @imports) is lost.
   Class names are recovered; rules are flat CSS that compiles as SCSS. */

:export {
  viewport_rf_width: 2800;
  viewport_rf_height: 1600;
  viewport_flex_height: min(57vw, 100vh);
  safeArea_paddingLeft: var(--safeArea_paddingLeft);
  safeArea_paddingRight: var(--safeArea_paddingRight);
  safeArea_paddingBottom: var(--safeArea_paddingBottom);
}

.rootContainer {
  width: 100%;
  height: 100%;
  position: relative;
  background-size: cover;
  background-position: center;
  overflow: hidden;
  text-align: center;
}

.mainBox {
  display: flex;
  position: relative;
  width: 100%;
  height: 100%;
  background-size: cover;
  background-position: center;
  color: #fff;
}

.leftBox {
  position: absolute;
  left: 0;
  top: 0;
  width: 50%;
  height: 100%;
  z-index: 1;
}

.rightBox {
  position: absolute;
  right: 0;
  top: 0;
  width: 50%;
  height: 100%;
}

.sectionsBox {
  width: 100%;
  height: 100%;
  overflow: hidden;
  display: flex;
  flex-direction: column;
  border: solid #d6ba84;
  border-width: 0 2px 0 0;
}

.sectionsBox .section:nth-child(2) {
  border: solid #d6ba84;
  border-width: 2px 0 2px 0;
}

.section {
  width: 100vw;
  height: 33.3%;
  display: flex;
  background-size: cover;
  background-position: center;
}

.sectionLeftBox {
  display: flex;
  width: 30vw;
}

.sectionRightBox {
  display: flex;
  flex: 1 1;
}

.arrow_ATK {
  height: 100%;
  z-index: 1;
}

.arrow_DEF {
  height: 100%;
  z-index: 1;
}

.sectionCont {
  flex: 1 1;
  display: flex;
  flex-direction: column;
  padding: 0.5rem 0 0.5rem 0;
  align-items: end;
  position: relative;
}

.sectionCont.right {
  align-items: start;
}

.zoneNameBox {
  display: flex;
  flex-direction: column;
  position: absolute;
  left: 0;
  top: 0;
  width: 100%;
}

.zoneName {
  color: #b89a5f;
  font-size: calc(min(57vw, 100vh) * 0.17125);
  line-height: calc(min(57vw, 100vh) * 0.17125);
  font-family: 'Noto Serif TC';
  font-family: var(--font_noto_serif);
  font-weight: 900;
  text-align: left;
  -webkit-filter: drop-shadow(0 0 0.5rem rgba(0, 0, 0, 0.7));
  filter: drop-shadow(0 0 0.5rem rgba(0, 0, 0, 0.7));
  white-space: nowrap;
}

.zoneBoost {
  flex: 1 1;
  font-family: 'Noto Sans TC';
  font-family: var(--font_noto_sans);
  font-size: calc(min(57vw, 100vh) * 0.03375);
  font-weight: bold;
  color: #d8c38a;
  text-align: center;
  padding-left: max(env(safe-area-inset-left), 59px);
  padding-left: var(--safeArea_paddingLeft);
  text-shadow: #000 0.1em 0.1em 0.2em;
}

.sectionContRow1 {
  position: relative;
  display: flex;
  justify-content: center;
  width: 16.0714285714vw;
  text-shadow: #000 0.1em 0.1em 0.2em;
}

.sectionContRow1Props {
  display: inline-flex;
  flex-direction: column;
}

.sectionProp1 {
  font-size: calc(min(57vw, 100vh) * 0.03375);
  font-family: 'Gelasio';
  font-family: var(--font_text_figures);
  font-weight: 900;
  height: calc(min(57vw, 100vh) * 0.046875);
}

.sectionProp2 {
  font-size: calc(min(57vw, 100vh) * 0.041875);
  font-family: 'Gelasio';
  font-family: var(--font_text_figures);
  font-weight: 900;
  height: calc(min(57vw, 100vh) * 0.059375);
}

.sectionProp3 {
  font-size: calc(min(57vw, 100vh) * 0.025);
  text-align: left;
  font-weight: bold;
  font-family: 'Noto Sans TC';
  font-family: var(--font_noto_sans);
  height: calc(min(57vw, 100vh) * 0.040625);
}

.sectionContRow2 {
  font-size: calc(min(57vw, 100vh) * 0.03375);
  font-weight: bold;
  color: #d8c38a;
  margin-top: calc(min(57vw, 100vh) * 0.03125);
  align-self: start;
  padding-left: max(env(safe-area-inset-left), 59px);
  padding-left: var(--safeArea_paddingLeft);
  font-family: 'Noto Sans TC';
  font-family: var(--font_noto_sans);
}

.toggleArrowBox {
  position: absolute;
  right: 0;
  top: 50%;
  height: 30%;
  -webkit-transform: translate(60%, -50%);
  transform: translate(60%, -50%);
}

.toggleArrowBox.toggled {
  -webkit-transform: translate(35%, -50%);
  transform: translate(35%, -50%);
}

.toggleArrow {
  height: 100%;
}

.sliderBox {
  position: absolute;
  left: 30vw;
  top: 0;
  width: calc(min(57vw, 100vh) * 0.1125);
  height: 100%;
  -webkit-transform: translateX(-50%);
  transform: translateX(-50%);
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 2;
}

.vertical_slider[data-vertical] {
  width: calc(min(57vw, 100vh) * 0.025);
  height: 66.6666666667%;
  background-color: #000;
  box-shadow: 0px 0px 20px 1px #fff;
}

.vertical_slider .range-slider__range {
  background: #000;
}

.vertical_slider .range-slider__thumb {
  width: calc(min(57vw, 100vh) * 0.125);
  height: calc(min(57vw, 100vh) * 0.125);
}

.vertical_slider .range-slider__thumb[data-lower] {
  background: url(data:image/png;base64,);
  background-position: center;
  background-size: contain;
}

.vertical_slider .range-slider__thumb[data-upper] {
  background: url(data:image/png;base64,);
  background-position: center;
  background-size: contain;
}
